//! Agreement with NuGet's own libraries (NuGet.Versioning, NuGet.Frameworks),
//! from a table generated by `tests/gen/Program.cs`.
use crate::{Framework, Range, Version};
use serde_json::Value;
use std::cmp::Ordering;

fn truth() -> Value {
    serde_json::from_str(include_str!("../tests/nuget_truth.json")).unwrap()
}

fn strings(v: &Value) -> Vec<&str> {
    v.as_array().unwrap().iter().map(|s| s.as_str().unwrap()).collect()
}

#[test]
fn agrees_with_nuget_on_what_is_a_version_and_how_it_is_normalised() {
    let t = truth();
    for s in strings(&t["valid"]) {
        let v = Version::parse(s).unwrap_or_else(|| panic!("{s:?} is a version"));
        assert_eq!(v.normalized(), t["normalized"][s].as_str().unwrap(), "normalised form of {s}");
    }
    for s in strings(&t["invalid"]) {
        assert!(Version::parse(s).is_none(), "{s:?} is not a version");
    }
}

#[test]
fn agrees_with_nuget_on_every_ordered_pair() {
    let t = truth();
    let mut checked = 0;
    for (pair, want) in t["order"].as_object().unwrap() {
        let (a, b) = pair.split_once(' ').unwrap();
        let want = match want.as_i64().unwrap() {
            -1 => Ordering::Less,
            0 => Ordering::Equal,
            _ => Ordering::Greater,
        };
        assert_eq!(Version::parse(a).unwrap().cmp(&Version::parse(b).unwrap()), want, "{a} vs {b}");
        checked += 1;
    }
    assert!(checked > 1500, "{checked} pairs");
}

#[test]
fn agrees_with_nuget_on_every_range_and_its_best_match() {
    let t = truth();
    let valid = strings(&t["valid"]);
    let all: Vec<Version> = valid.iter().map(|s| Version::parse(s).unwrap()).collect();
    let (mut checked, mut invalid) = (0, 0);
    for (range, accepted) in t["ranges"].as_object().unwrap() {
        if accepted.is_null() {
            assert!(Range::parse(range).is_none(), "{range:?} is not a range");
            invalid += 1;
            continue;
        }
        let parsed = Range::parse(range).unwrap_or_else(|| panic!("{range:?} is a range"));
        let accepted = strings(accepted);
        for (text, v) in valid.iter().zip(&all) {
            assert_eq!(parsed.satisfied_by(v), accepted.contains(text), "does {range:?} accept {text}?");
            checked += 1;
        }
        // The version a restore would pick: the lowest that fits.
        let best = parsed.best_match(&all).map(|v| v.normalized());
        assert_eq!(best.as_deref(), t["best"][range].as_str(), "best match for {range:?}");
    }
    assert!(checked > 1000 && invalid > 5, "{checked} checks, {invalid} invalid ranges");
}

#[test]
fn agrees_with_nuget_on_which_dependency_group_a_project_uses() {
    let t = truth();
    let mut checked = 0;
    for (case, want) in t["nearest"].as_object().unwrap() {
        let (project, groups) = case.split_once(" <- ").unwrap();
        let names: Vec<&str> = groups.split('|').collect();
        let parsed: Vec<Framework> = names.iter().map(|g| Framework::parse(g)).collect();
        let got = Framework::parse(project).nearest(&parsed).map(|i| names[i]);
        assert_eq!(got, want.as_str(), "{case}");
        checked += 1;
    }
    assert!(checked > 100, "{checked} cases");
}
